#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

vector<vector<long long>> matrixPower(const vector<vector<long long>>& base, long long exp);
vector<vector<long long>> identity(int size);
vector<vector<long long>> multiply(const vector<vector<long long>>& a, const vector<vector<long long>>& b);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, L, R;
    cin >> n >> m >> L >> R;
    long long h = R - L;

    long long e = 0, o = 0;
    if (h % 2 == 1) {
        long long d = (h + 1) / 2;
        e = d;
        o = d;
    } else {
        long long d = h / 2;
        e = d;
        o = d;
        if (L % 2 == 1) o++;
        else e++;
    }

    vector<vector<long long>> matrix = {{e, o}, {o, e}};
    vector<vector<long long>> result = matrixPower(matrix, n * m);
    long long ans = result[0][0];
    if ((n * m) % 2 == 1) ans += result[0][1];
    cout << ans % mod << "\n";

    return 0;
}

vector<vector<long long>> matrixPower(const vector<vector<long long>>& base, long long exp) {
    if (exp == 0) return identity(base.size());
    if (exp % 2 == 1) {
        vector<vector<long long>> temp = matrixPower(base, exp - 1);
        return multiply(temp, base);
    }
    vector<vector<long long>> half = matrixPower(base, exp / 2);
    return multiply(half, half);
}

vector<vector<long long>> identity(int size) {
    vector<vector<long long>> id(size, vector<long long>(size, 0));
    for (int i = 0; i < size; i++) {
        id[i][i] = 1;
    }
    return id;
}

vector<vector<long long>> multiply(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int rows = a.size();
    int cols = b[0].size();
    int inner = a[0].size();
    vector<vector<long long>> res(rows, vector<long long>(cols, 0));
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            for (int k = 0; k < inner; k++) {
                res[i][j] += (a[i][k] % mod) * (b[k][j] % mod);
                res[i][j] %= mod;
            }
        }
    }
    return res;
}

